async function saveComboOfDay(day){
  try{
    const sel=$(`codPack${day}`)?.value||'';
    const name=($(`codName${day}`)?.value||'').trim();
    const enabled=Boolean($(`codEnabled${day}`)?.checked);
    if(!sel){toast('Choose a combo or family pack first');return;}
    const [packId,packType]=sel.split('|');
    await api('/api/combo-of-day',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({day:String(day),packId,packType,name,enabled})});
    toast(`${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][Number(day)]} combo saved`);
    await navigate('comboofday');
  }catch(e){toast(e.message)}
}
async function clearComboOfDay(day){
  if(!confirm("Clear this day's Combo of the Day?"))return;
  try{
    await api('/api/combo-of-day/'+encodeURIComponent(day),{method:'DELETE'});
    toast('Combo of the Day cleared');
    await navigate('comboofday');
  }catch(e){toast(e.message)}
}
function ensureV6AdminStyles(){if(document.getElementById('tpp-v6-admin-styles'))return;const st=document.createElement('style');st.id='tpp-v6-admin-styles';st.textContent='.sales-tooltip{position:fixed;z-index:9999;pointer-events:none;padding:8px 10px;border:1px solid rgba(255,179,71,.35);border-radius:10px;background:#111820;color:#fff;box-shadow:0 10px 30px rgba(0,0,0,.25);font-size:12px;display:flex;gap:8px;align-items:center}.sales-tooltip strong{font-weight:700}.sales-tooltip span{color:#ffb34f;font-weight:800}.raw-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.raw-card{margin:0}.raw-stock{display:flex;align-items:baseline;gap:8px;margin:12px 0}.raw-stock strong{font-size:30px}.raw-stock span{color:var(--muted);font-size:12px}.raw-actions{display:flex;flex-wrap:wrap;gap:6px}.day-offer-row{display:grid;grid-template-columns:100px 1.4fr 1fr auto auto;gap:8px;align-items:center;padding:11px 0;border-bottom:1px solid rgba(255,255,255,.06)}.cod-enabled{font-size:11px;color:var(--muted);white-space:nowrap}';document.head.appendChild(st)}
function showSalesTip(e,el){const tip=$('salesTooltip');if(!tip)return;tip.hidden=false;tip.innerHTML=`<strong>${esc(el.dataset.salesDate||'')}</strong><span>${money(Number(el.dataset.salesValue||0))}</span>`;tip.style.left=Math.min(window.innerWidth-170,Math.max(8,e.clientX+12))+'px';tip.style.top=Math.max(8,e.clientY-60)+'px'}function hideSalesTip(){const tip=$('salesTooltip');if(tip)tip.hidden=true}

function progressRows(rows){if(!rows.length)return '<div class="muted">No data</div>';const max=Math.max(...rows.map(x=>x.value),1);return `<div class="progress-list">${rows.map(x=>`<div class="progress-row"><span>${esc(x.name)}</span><span class="track"><i style="width:${(x.value/max)*100}%"></i></span><b>${money(x.value)}</b></div>`).join('')}</div>`}

function stockItemRow(i){return `<div class="stock-row" data-stock-name="${esc(i.name).toLowerCase()}" data-stock-cat="${esc(i.category)}" data-stock-status="${i.available===false?'sold':'available'}" style="display:flex;align-items:center;justify-content:space-between;gap:12px;padding:13px 0;border-bottom:1px solid rgba(255,255,255,.06)"><div style="min-width:0"><b>${esc(i.name)}</b><div class="muted" style="font-size:11px">${esc(i.id)} · ${esc(i.category)}</div></div><div style="display:flex;align-items:center;gap:8px"><span class="pill ${i.available===false?'red':'green'}">${i.available===false?'SOLD OUT':'AVAILABLE'}</span><button class="btn small ${i.available===false?'success':'danger'}" onclick="toggleAvail('${i.id}',${i.available===false})">${i.available===false?'Mark Available':'Mark Sold Out'}</button></div></div>`}
function stockPackRow(p){return `<div class="stock-row" data-stock-name="${esc(p.name).toLowerCase()}" data-stock-cat="${p.__type}" data-stock-status="${p.available===false?'sold':'available'}" style="display:flex;align-items:center;justify-content:space-between;gap:12px;padding:13px 0;border-bottom:1px solid rgba(255,255,255,.06)"><div style="min-width:0"><b>${esc(p.name)}</b><div class="muted" style="font-size:11px">${esc(p.id)} · ${p.__type==='family'?'Family Pack':'Combo'}</div></div><div style="display:flex;align-items:center;gap:8px"><span class="pill ${p.available===false?'red':'green'}">${p.available===false?'SOLD OUT':'AVAILABLE'}</span><button class="btn small ${p.available===false?'success':'danger'}" onclick="togglePackAvail('${p.__type}','${p.id}',${p.available!==false})">${p.available===false?'Mark Available':'Mark Sold Out'}</button></div></div>`}
function filterStock(){const q=($('stockSearch')?.value||'').toLowerCase();const filter=$('stockCat')?.value||'';document.querySelectorAll('#stockMenuList .stock-row').forEach(r=>{const okQ=!q||r.dataset.stockName.includes(q);const okFilter=!filter||(filter==='__sold'?r.dataset.stockStatus==='sold':filter==='__available'?r.dataset.stockStatus==='available':r.dataset.stockCat===filter);r.style.display=okQ&&okFilter?'flex':'none'})}
async function togglePackAvail(type,id,available){try{const d=await api('/api/packs/'+type+'/'+id);const p=d.packs.find(x=>x.id===id);if(!p)return;await api('/api/packs/'+type+'/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:p.name,price:Number(p.price),cost:Number(p.cost||0),image:p.image||'',description:p.description||'',items:Array.isArray(p.items)?p.items:[],available})});toast(available?'Pack available':'Pack sold out');navigate('stock')}catch(e){toast(e.message)}}

function menuRow(i){return `<tr data-name="${esc(i.name).toLowerCase()}" data-cat="${esc(i.category)}"><td><b>${esc(i.name)}</b><div class="muted">${esc(i.id)}</div></td><td>${money(i.price)}</td><td><input style="width:90px" id="cost_${i.id}" type="number" value="" placeholder="0"></td><td>${i.image?.startsWith('/uploads/')?`<div style="display:flex;align-items:center;gap:6px"><img src="${esc(i.image)}" alt="" style="width:38px;height:38px;object-fit:cover;border-radius:8px"><span class="pill blue">Uploaded</span></div>`:esc(i.image||'—')}</td><td><button class="btn small" onclick="editMenu('${i.id}')">Edit</button> <button class="btn small danger" onclick="deleteMenuItem('${esc(i.id)}')">Delete</button></td></tr>`}
