function newMenuItem(){const cats=(catalog?.categories||[]);openModal(`<div class="modal-head"><h2>New Dish</h2><button class="btn" onclick="closeModal()">✕</button></div><div class="formgrid"><div class="field full"><label>Section / Category</label><select id="nmCat">${cats.map(c=>`<option value="${esc(c.key)}">${esc(c.emoji||'🍽️')} ${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Dish name</label><input id="nmName" placeholder="e.g. Paneer Momos"></div><div class="field"><label>Price</label><input id="nmPrice" type="number" min="0"></div><div class="field"><label>Food cost</label><input id="nmCost" type="number" min="0" value="0"></div><div class="field full"><label>Dish image</label><input id="nmImageFile" type="file" accept="image/jpeg,image/png,image/webp"><small class="muted">Upload the dish photo directly from your phone.</small></div></div><p class="muted" style="font-size:11px">New dishes are added immediately to the customer website in the selected section.</p><button class="btn primary" onclick="createMenuItem()">Create Dish</button>`)}
function newCategory(){openModal(`<div class="modal-head"><h2>New Menu Section</h2><button class="btn" onclick="closeModal()">✕</button></div><div class="formgrid"><div class="field full"><label>Section name</label><input id="ncName" placeholder="e.g. Momos"></div><div class="field"><label>Emoji</label><input id="ncEmoji" value="🥟" maxlength="4"></div></div><p class="muted" style="font-size:11px">Example: create “Momos”, save it, then use + New Dish to add Momos items.</p><button class="btn primary" onclick="createCategory()">Create Section</button>`)}
async function createCategory(){try{await api('/api/categories',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:$('ncName').value,emoji:$('ncEmoji').value})});closeModal();await navigate('menu');toast('Menu section created')}catch(e){toast(e.message)}}
async function deleteCategory(key){const cat=(catalog?.categories||[]).find(c=>c.key===key);if(!cat)return;if(!confirm(`Delete the section “${cat.name}” and all dishes inside it?`))return;try{await api('/api/categories/'+encodeURIComponent(key),{method:'DELETE'});toast('Menu section deleted');await navigate('menu')}catch(e){toast(e.message)}}
async function uploadMenuImage(file){
  if(!file)return '';
  return new Promise((resolve,reject)=>{
    const reader=new FileReader();
    reader.onload=async()=>{
      try{
        const d=await api('/api/upload-image',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:file.name,mime:file.type,data:reader.result})});
        resolve(d.path||'');
      }catch(e){reject(e)}
    };
    reader.onerror=()=>reject(new Error('Could not read image.'));
    reader.readAsDataURL(file);
  });
}
async function createMenuItem(){
  try{
    const file=$('nmImageFile')?.files?.[0];
    const image=await uploadMenuImage(file);
    await api('/api/menu',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({category:$('nmCat').value,name:$('nmName').value,price:Number($('nmPrice').value),cost:Number($('nmCost').value),image})});
    closeModal();await navigate('menu');toast('Menu item created');
  }catch(e){toast(e.message)}
}
