async function editMenu(id){const item=catalog.categories.flatMap(c=>c.items).find(x=>x.id===id);if(!item)return;const cost='';openModal(`<div class="modal-head"><h2>Edit ${esc(item.id)}</h2><button class="btn" onclick="closeModal()">✕</button></div><div class="formgrid"><div class="field"><label>Name</label><input id="mName" value="${esc(item.name)}"></div><div class="field"><label>Price</label><input id="mPrice" type="number" value="${Number(item.price)}"></div><div class="field"><label>Food cost</label><input id="mCost" type="number" placeholder="0"></div><div class="field"><label>Dish image</label><input id="mImageFile" type="file" accept="image/jpeg,image/png,image/webp"><small class="muted">${item.image?`Current: ${esc(item.image)}`:'No image currently set'}</small></div><div class="field"><label>Kannada</label><input id="mKn" value="${esc(item.translations?.kn||'')}"></div><div class="field"><label>Hindi</label><input id="mHi" value="${esc(item.translations?.hi||'')}"></div><div class="field"><label>Urdu</label><input id="mUr" value="${esc(item.translations?.ur||'')}"></div></div><div style="display:flex;justify-content:flex-end;gap:8px"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveMenu('${id}')">Save</button></div>`)}
async function saveMenu(id){
  try{
    const current=catalog?.categories?.flatMap(c=>c.items||[]).find(x=>x.id===id);
    const file=$('mImageFile')?.files?.[0];
    const image=file ? await uploadMenuImage(file) : (current?.image||'');
    await api('/api/menu/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:$('mName').value,price:Number($('mPrice').value),cost:Number($('mCost').value||0),image,translations:{kn:$('mKn').value,hi:$('mHi').value,ur:$('mUr').value}})});
    toast('Menu updated');closeModal();navigate('menu');
  }catch(e){toast(e.message)}
}
async function toggleAvail(id,available){try{await api('/api/availability/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({available})});toast(available?'Item available':'Item sold out');await navigate(currentPage)}catch(e){toast(e.message)}}
function packCard(p,type){return `<div class="card" style="margin-bottom:10px"><div style="display:flex;justify-content:space-between;gap:10px"><div><b>${esc(p.name)}</b><div class="muted">${esc(p.id)}</div></div>${statusPill(p.available?'available':'sold out')}</div><p class="muted" style="margin:8px 0">${esc(p.description||'')}</p><div style="display:flex;justify-content:space-between;align-items:center"><b>${money(p.price)}</b><button class="btn small" onclick="editPack('${type}','${p.id}')">Edit</button></div></div>`}
async function editPack(type,id){const d=await api('/api/packs/'+type);const p=d.packs.find(x=>x.id===id);openModal(`<div class="modal-head"><h2>Edit ${esc(id)}</h2><button class="btn" onclick="closeModal()">✕</button></div><div class="formgrid"><div class="field"><label>Name</label><input id="pName" value="${esc(p.name)}"></div><div class="field"><label>Price</label><input id="pPrice" type="number" value="${Number(p.price)}"></div><div class="field"><label>Food cost</label><input id="pCost" type="number" value="${Number(p.cost||0)}"></div><div class="field"><label>Pack image</label><input id="pImageFile" type="file" accept="image/jpeg,image/png,image/webp"><div class="muted">${p.image?`Current: ${esc(p.image)}`:'No image yet.'}</div></div><div class="field full"><label>Description</label><textarea id="pDesc">${esc(p.description||'')}</textarea></div><div class="field full"><label>Items (one per line)</label><textarea id="pItems" rows="5">${esc((p.items||[]).join('\n'))}</textarea></div></div><button class="btn primary" onclick="savePack('${type}','${id}')">Save</button>`)}
function newPack(type){openModal(`<div class="modal-head"><h2>New ${type==='family'?'Family Pack':'Combo'}</h2><button class="btn" onclick="closeModal()">✕</button></div><div class="formgrid"><div class="field"><label>Name</label><input id="npName"></div><div class="field"><label>Price</label><input id="npPrice" type="number"></div><div class="field"><label>Food cost</label><input id="npCost" type="number"></div><div class="field"><label>Pack image</label><input id="npImageFile" type="file" accept="image/jpeg,image/png,image/webp"></div><div class="field full"><label>Description</label><textarea id="npDesc"></textarea></div><div class="field full"><label>Items, one per line</label><textarea id="npItems" rows="5"></textarea></div></div><button class="btn primary" onclick="createPack('${type}')">Create</button>`)}
async function uploadFormImage(inputId){const f=$(inputId)?.files?.[0];if(!f)return '';const reader=new FileReader();return new Promise((resolve,reject)=>{reader.onload=async()=>{try{const d=await api('/api/upload-image',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:f.name,mime:f.type,data:reader.result})});resolve(d.path||'')}catch(e){reject(e)}};reader.onerror=()=>reject(new Error('Could not read image'));reader.readAsDataURL(f);})}
async function savePack(type,id){try{let image=await uploadFormImage('pImageFile');if(!image){const d=await api('/api/packs/'+type);image=d.packs.find(x=>x.id===id)?.image||'';}await api('/api/packs/'+type+'/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:$('pName').value,price:Number($('pPrice').value),cost:Number($('pCost').value),image,description:$('pDesc').value,items:$('pItems').value.split('\n').map(x=>x.trim()).filter(Boolean)})});closeModal();navigate('packs');toast('Pack updated')}catch(e){toast(e.message)}}
async function createPack(type){try{const image=await uploadFormImage('npImageFile');await api('/api/packs/'+type,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:$('npName').value,price:Number($('npPrice').value),cost:Number($('npCost').value),image,description:$('npDesc').value,items:$('npItems').value.split('\n').map(x=>x.trim()).filter(Boolean)})});closeModal();navigate('packs');toast('Pack created')}catch(e){toast(e.message)}}
function rawMaterialCard(m){
  const qty=Number(m.quantity||0), low=Number(m.lowStock||0), usage=Number(m.usagePerDish||0);
  const lowClass=low>0 && qty<=low ? 'red' : 'green';
  return `<div class="card raw-card">
    <div style="display:flex;justify-content:space-between;gap:10px;align-items:flex-start">
      <div><h3 style="margin-bottom:4px">${esc(m.name)}</h3><div class="muted">${esc(m.category)} · ${esc(m.unit||'pcs')} · uses ${usage} / dish</div></div>
      <span class="pill ${lowClass}">${low>0&&qty<=low?'LOW STOCK':'STOCK OK'}</span>
    </div>
    <div class="raw-stock"><strong>${qty}</strong><span>${esc(m.unit||'units')} remaining</span></div>
    ${low>0?`<div class="muted" style="font-size:11px;margin-bottom:9px">Low-stock alert at ${low} ${esc(m.unit||'units')}</div>`:''}
    <div class="raw-actions">
      <button class="btn small" onclick="adjustRawMaterial('${esc(m.id)}',-1)">−1</button>
      <button class="btn small" onclick="adjustRawMaterial('${esc(m.id)}',1)">+1</button>
      <button class="btn small" onclick="adjustRawMaterial('${esc(m.id)}',10)">+10</button>
      <button class="btn small" onclick="setRawMaterialQuantity('${esc(m.id)}')">Set Qty</button>
      <button class="btn small" onclick="editRawMaterial('${esc(m.id)}')">Edit</button>
      <button class="btn small danger" onclick="deleteRawMaterial('${esc(m.id)}')">Delete</button>
    </div>
  </div>`;
}
function rawCategoryOptions(selected=''){
  return (catalog?.categories||[]).map(c=>`<option value="${esc(c.key)}" ${String(c.key)===String(selected)?'selected':''}>${esc(c.emoji||'🍽️')} ${esc(c.name)}</option>`).join('');
}
function rawMaterialForm(title,m={}){
  return `<div class="modal-head"><h2>${esc(title)}</h2><button class="btn" onclick="closeModal()">✕</button></div>
    <div class="formgrid">
      <div class="field full"><label>Raw material name</label><input id="rmName" value="${esc(m.name||'')}" placeholder="e.g. Pizza Base"></div>
      <div class="field"><label>Menu section</label><select id="rmCat">${rawCategoryOptions(m.category||'')}</select></div>
      <div class="field"><label>Unit</label><input id="rmUnit" value="${esc(m.unit||'pcs')}" placeholder="pcs, kg, litre"></div>
      <div class="field"><label>Current quantity</label><input id="rmQty" type="number" min="0" step="0.01" value="${Number(m.quantity||0)}"></div>
      <div class="field"><label>Usage per ordered dish</label><input id="rmUsage" type="number" min="0" step="0.01" value="${Number(m.usagePerDish===undefined?1:m.usagePerDish)}"><small class="muted">Example: 1 pizza uses 1 base.</small></div>
      <div class="field"><label>Low-stock alert level</label><input id="rmLow" type="number" min="0" step="0.01" value="${Number(m.lowStock||0)}"></div>
    </div>`;
}
async function newRawMaterial(){
  if(!catalog){try{const d=await api('/api/menu');catalog=d.catalog;}catch(e){toast(e.message);return;}}
  openModal(rawMaterialForm('Add Raw Material')+`<div style="display:flex;justify-content:flex-end;gap:8px;margin-top:12px"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="createRawMaterial()">Add Raw Material</button></div>`);
}
async function createRawMaterial(){
  const payload={name:$('rmName')?.value||'',category:$('rmCat')?.value||'',unit:$('rmUnit')?.value||'pcs',quantity:Number($('rmQty')?.value||0),usagePerDish:Number($('rmUsage')?.value||0),lowStock:Number($('rmLow')?.value||0)};
  try{await api('/api/raw-materials',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});closeModal();toast('Raw material added');await navigate('rawmaterials');}
  catch(e){toast(e.message)}
}
async function editRawMaterial(id){
  const d=await api('/api/raw-materials');const m=(d.rawMaterials||[]).find(x=>x.id===id);if(!m){toast('Raw material not found');return;}
  openModal(rawMaterialForm('Edit Raw Material',m)+`<div style="display:flex;justify-content:flex-end;gap:8px;margin-top:12px"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveRawMaterial('${esc(id)}')">Save Changes</button></div>`);
}
async function saveRawMaterial(id){
  const payload={name:$('rmName')?.value||'',category:$('rmCat')?.value||'',unit:$('rmUnit')?.value||'pcs',quantity:Number($('rmQty')?.value||0),usagePerDish:Number($('rmUsage')?.value||0),lowStock:Number($('rmLow')?.value||0)};
  try{await api('/api/raw-materials/'+encodeURIComponent(id),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});closeModal();toast('Raw material updated');await navigate('rawmaterials');}
  catch(e){toast(e.message)}
}
async function adjustRawMaterial(id,delta){
  try{await api('/api/raw-materials/'+encodeURIComponent(id)+'/adjust',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({delta})});toast(delta>0?'Stock increased':'Stock decreased');await navigate('rawmaterials');}
  catch(e){toast(e.message)}
}
async function setRawMaterialQuantity(id){
  const raw=await api('/api/raw-materials');const m=(raw.rawMaterials||[]).find(x=>x.id===id);if(!m)return;
  const value=prompt(`Enter new quantity for ${m.name}`,String(Number(m.quantity||0)));if(value===null)return;
  const qty=Number(value);if(!Number.isFinite(qty)||qty<0){toast('Enter a valid quantity');return;}
  try{await api('/api/raw-materials/'+encodeURIComponent(id),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:m.name,category:m.category,unit:m.unit,quantity:qty,usagePerDish:m.usagePerDish,lowStock:m.lowStock})});toast('Quantity updated');await navigate('rawmaterials');}
  catch(e){toast(e.message)}
}
async function deleteRawMaterial(id){
  const raw=await api('/api/raw-materials');const m=(raw.rawMaterials||[]).find(x=>x.id===id);if(!m)return;
  if(!confirm(`Delete raw material “${m.name}”?`))return;
  try{await api('/api/raw-materials/'+encodeURIComponent(id),{method:'DELETE'});toast('Raw material deleted');await navigate('rawmaterials');}
  catch(e){toast(e.message)}
}

