async function saveMarketing(){const bh={};const daySpecials={};for(let i=0;i<7;i++){const el=document.getElementById('special'+i);daySpecials[i]=el?[...el.selectedOptions].map(o=>o.value):(settings.daySpecials?.[i]||[]);}for(let i=0;i<7;i++)bh[i]={enabled:$('hEn'+i).checked,open:$('hOpen'+i).value,close:$('hClose'+i).value};try{const payload={settings:{manualClosed:$('manualClosed').checked,pauseNewOrders:$('pauseOrders').checked,enforceBusinessHours:$('enforceHours').checked,announcement:{enabled:$('annEnabled').checked,text:$('annText').value},banner:{enabled:$('banEnabled').checked,eyebrow:$('banEy').value,title:$('banTitle').value,body:$('banBody').value,villages:$('banVill').value},campaign:{enabled:$('campEnabled').checked,title:$('campTitle').value,body:$('campBody').value,startsOn:$('campStart').value,endsOn:$('campEnd').value},businessHours:bh,daySpecials}};const d=await api('/api/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});settings=d.settings||settings;updateStatus();toast('Settings saved');}catch(e){toast(e.message)}}
