function openAssignDriver(orderId){const active=(drivers||[]).filter(d=>d.active!==false);if(!active.length){toast('Add an active driver first.');return;}openModal(`<div class="modal-head"><h2>Assign Delivery Driver</h2><button class="btn" onclick="closeModal()">✕</button></div><p class="muted">Choose who is taking this order. If no one is assigned within 5 minutes, the first active driver will be assigned automatically.</p><div class="field"><label>Driver</label><select id="assignDriverSelect">${active.map(d=>`<option value="${esc(d.id)}">${esc(d.name)} — ${esc(d.phone)}</option>`).join('')}</select></div><button class="btn primary" onclick="assignDriver('${esc(orderId)}')">Assign Driver</button>`)}
async function assignDriver(orderId){const driverId=$('assignDriverSelect')?.value;if(!driverId)return;try{await api('/api/orders/'+encodeURIComponent(orderId)+'/assign-driver',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({driverId})});closeModal();toast('Driver assigned');await navigate('orders')}catch(e){toast(e.message)}}
async function markCod(id){try{const d=await api('/api/orders/'+encodeURIComponent(id));const o=d.order;await api('/api/orders/'+encodeURIComponent(id)+'/meta',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({notes:o.admin?.notes||'',customerNote:o.admin?.customerNote||'',driver:o.admin?.driver||'',driverPhone:o.admin?.driverPhone||'',codCollected:true,cashReceived:Number(o.total||0)})});toast('COD marked collected');navigate('orders')}catch(e){toast(e.message)}}
async function globalSearch(){const q=($('globalSearch')?.value||'').trim();if(q.length<2){toast('Type at least 2 characters');return}try{const d=await api('/api/search?q='+encodeURIComponent(q));openModal(`<div class="modal-head"><h2>Global Search</h2><button class="btn" onclick="closeModal()">✕</button></div>${d.results.length?d.results.map(r=>`<div class="list-row"><div><b>${esc(r.title)}</b><div class="muted">${esc(r.subtitle||'')}</div></div><span class="pill gray">${esc(r.type)}</span></div>`).join(''):'<div class="empty muted">No matching orders, products or packs.</div>'}`)}catch(e){toast(e.message)}}
